use serde_json::{json,Value};
use crate::{java_runtime::Rc,cn::wps::moss::{engine::grid::MemoryMixSQLStringList::MemoryMixSQLStringList,filefmt::biff8::record::common::{UnicodeString::UnicodeString,FormatRun::FormatRun},util::objpool::ConcurrentArrayQueue::ConcurrentArrayQueue}};
use sha2::{Sha256,Digest};
fn base64(bytes:&[u8])->String{let alphabet=b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";let mut out=String::new();for part in bytes.chunks(3){let v=((part[0]as u32)<<16)|((part.get(1).copied().unwrap_or(0)as u32)<<8)|part.get(2).copied().unwrap_or(0)as u32;for i in 0..4{out.push(if i>part.len(){'='}else{alphabet[((v>>(18-i*6))&63)as usize]as char});}}out}
fn decode(s:&str)->Vec<u8>{let alphabet=b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";let mut out=vec![];for group in s.as_bytes().chunks(4){let mut bits=0u32;for b in group{bits=(bits<<6)|if *b==b'='{0}else{alphabet.iter().position(|c|c==b).unwrap()as u32};}out.push((bits>>16)as u8);if group[2]!=b'='{out.push((bits>>8)as u8);}if group[3]!=b'='{out.push(bits as u8);}}out}
fn observe(f:impl FnOnce()->Value)->Value{match std::panic::catch_unwind(std::panic::AssertUnwindSafe(f)){Ok(v)=>v,Err(e)=>{let s=e.downcast_ref::<String>().cloned().or_else(||e.downcast_ref::<&str>().map(|s|s.to_string())).unwrap_or_default();if s.contains("IllegalArgumentException"){json!("IllegalArgumentException")}else if s.contains("index out of bounds")||s.contains("ArrayIndexOutOfBoundsException"){json!("ArrayIndexOutOfBoundsException")}else if s.contains("IndexOutOfBoundsException"){json!("IndexOutOfBoundsException")}else{panic!("unexpected native failure {s}")}}}}
fn contents(channel:&mut FileChannel)->Value{let mut bytes=vec![0;channel.size().unwrap()as usize];channel.read(&mut bytes,0).unwrap();json!(base64(&bytes))}
fn bytes(input:&Value)->Value{let mut out=vec![];for mode in 0..2{let mut p=ByteArrayPersistence::ByteArrayPersistence();if mode==1{p.channel=None;}let mut stages=vec![json!({"empty":observe(||json!(p.insertData(&[])))})];let mut count=0i32;for block in input["bytes"].as_array().unwrap(){let values:Vec<_>=block.as_array().unwrap().iter().map(|v|decode(v.as_str().unwrap())).collect();let insert=observe(||json!(p.insertData(&values)));count+=values.len()as i32;let mut rows=vec![];for id in [0,1,count-1,-1]{let value=observe(||json!(p.queryData(id).map(|v|base64(&v))));rows.push(json!({"id":id,"value":value}));}let mut row=json!({"insert":insert,"queries":rows});if mode==0{row["file"]=contents(p.channel.as_mut().unwrap());}stages.push(row);}p.closeChannel();let closed:Vec<_>=[0,count-1].into_iter().map(|id|observe(||json!(p.queryData(id)))).collect();let insert=observe(||json!(p.insertData(&[vec![1,2]])));out.push(json!({"mode":mode,"stages":stages,"closed":closed,"closedInsert":insert}));}json!(out)}
fn doubles(input:&Value)->Value{let mut out=vec![];byteBuffer8.clear();for mode in 0..2{let mut p=DoubleArrayPersistence::DoubleArrayPersistence();if mode==1{p.channel=None;}let mut stages=vec![];let mut count=0i32;for block in input["doubles"].as_array().unwrap(){let values:Vec<_>=block.as_array().unwrap().iter().map(|v|f64::from_bits(u64::from_str_radix(v.as_str().unwrap(),16).unwrap())).collect();let insert=observe(||json!(p.insertData(&values)));count+=values.len()as i32;let mut rows=vec![];for id in [-1,0,count-1,count,count+1,i32::MIN,i32::MAX]{rows.push(json!({"id":id,"bits":format!("{:016x}",p.queryData(id).to_bits())}));}let mut row=json!({"insert":insert,"queries":rows});if mode==0{row["file"]=contents(p.channel.as_mut().unwrap());}stages.push(row);}p.closeChannel();let closed=format!("{:016x}",p.queryData(0).to_bits());let insert=observe(||json!(p.insertData(&[])));out.push(json!({"mode":mode,"stages":stages,"closed":closed,"closedInsert":insert}));}json!(out)}
fn spill()->Value{let mut strings=MemoryMixSQLStringList::MemoryMixSQLStringList();strings.addStrsByOOXML(&[],0,0,true);let mut ids=vec![];for i in 0..25008{let id=strings.addString(Some(&format!("spill{i}")));if i>=24995{ids.push(id);}}let mut rich=UnicodeString::new("富😀tail".into());rich.resetFormatRuns(vec![FormatRun::new(1,2)]);let rich=Rc::new(rich);let richId=strings.addUnicodeString(Some(rich.clone()));let count=strings.allStrs.len()as i32+strings.existedStringCount;let persisted=strings.existedStringCount;let mut it=strings.getStrStoreIterator();let mut rows=vec![];let mut hash=Sha256::new();let mut i=0;while it.hasNext(){let value=it.next();hash.update(value.getString().as_bytes());hash.update([0,value.getFormatRunCount()as u8]);if i<10||i>=24995{rows.push(json!({"id":i,"text":value.getString(),"runs":value.getFormatRunCount(),"sameRich":Rc::ptr_eq(&value,&rich)}));}i+=1;}json!({"count":count,"visited":i,"ids":ids,"richId":richId,"rows":rows,"sha256":format!("{:x}",hash.finalize()),"persisted":persisted})}
fn queues()->Value{let mut out=vec![];for capacity in [0,1,2,5]{let q=ConcurrentArrayQueue::ConcurrentArrayQueue(capacity);let mut rows=vec![];for i in 0..40{let value=match i%7{0=>json!(q.tryPush(Some(i))),1=>json!(q.push(Some(i))),2=>json!(q.tryPop()),3=>json!(q.pop()),4=>json!(q.tryPush(None)),5=>{q.clear();json!("clear")},_=>json!(q.size())};rows.push(json!({"value":value,"size":q.size()}));}out.push(rows);}json!(out)}
#[test]
fn original_android_persistence_files_blocks_spill_and_queues(){let path=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("rewrite-review/milestones/m4-edit-save/evidence/persistence-r0b34");let j:Value=serde_json::from_slice(&std::fs::read(path.join("java.json")).unwrap()).unwrap();let input:Value=serde_json::from_slice(&std::fs::read(path.join("inputs.json")).unwrap()).unwrap();let actual=json!({"bytes":bytes(&input),"doubles":doubles(&input),"spill":spill(),"queues":queues()});std::fs::write(path.join("rust.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();compare(&actual,&j,"root");}

fn compare(a:&Value,b:&Value,path:&str){match(a,b){(Value::Object(x),Value::Object(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(k,v)in x{compare(v,y.get(k).unwrap(),&format!("{path}.{k}"));}},(Value::Array(x),Value::Array(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(i,(a,b))in x.iter().zip(y).enumerate(){compare(a,b,&format!("{path}[{i}]"));}},_=>assert_eq!(a,b,"{path}")}}
